summaries = evoto.edit.status(12345, image_ids=[101, 202])
for item in summaries:
    print(item['image_id'], item.get('has_edit'), item.get('has_color'), item.get('has_crop'))

presets = evoto.export.list_export_presets()
for p in presets:
    print(p['name'], p['uuid'])

def on_failed(data):
    print('Export failed:', data.get('message'))

evoto.export.on_failed(on_failed)

def on_item(data):
    print('Item done:', data.get('output_path'))

evoto.export.on_item_finished(on_item)

def on_started(data):
    print('Export started:', data)

evoto.export.on_started(on_started)

images = evoto.image.list(use_current_project=True)
for img in images:
    print(img['id'], img['filename'])

def on_completed(data):
    print('Import completed:', data)

evoto.image.on_completed(on_completed)

def on_failed(data):
    print('Import failed:', data.get('message'))

evoto.image.on_failed(on_failed)

def on_progress(data):
    print('Import progress:', data.get('progress', 0))

evoto.image.on_progress(on_progress)

