spaces = evoto.library.list_spaces()
for space in spaces:
    print(space['space_id'], space['name'], space['type'])

from evoto.core.api_fields import MetadataField

result = evoto.metadata.write(
    [101, 202],
    {
        MetadataField.TITLE: "Client selects",
        MetadataField.RATING: 5,
    },
)
print(result.get('success_count'), result.get('failed_count'))

categories = evoto.preset.list()
for cat in categories:
    print(cat['name'], len(cat['presets']), 'presets')

try:
    proj = evoto.project.current()
    print('Active project:', proj['name'])
except ApiError as e:
    if e.code == 404:
        print('No project is open')

groups = evoto.project.group_list()
for group in groups:
    print(group['id'], group['name'])

projects = evoto.project.list(use_current_group=True)
for p in projects:
    print(p['name'])

images = evoto.watcher.list_unexported(12345)
for img in images:
    print(img['filename'])

def on_new(data):
    for f in data['files']:
        print('New file:', f)

evoto.watcher.on_files_added(on_new)

import evoto

@evoto.task
def hello(name: str) -> str:
    return f"Hello, {name}!"

evoto.run()

def on_export_done(data):
    print('Export completed:', data)

evoto.on('export.completed', on_export_done)

def done(result, status):
    print('async result:', result)

req_id = evoto.host.call_async('image.list', {}, done)
